<script>
 import {onMount,onDestroy,untrack} from 'svelte';
 let {source,recordings=[],revision,request,selectedMomentId='',onMomentChange=()=>{},onSelection=()=>{},onUseMoment=()=>{},onSaved=()=>{},onDirtyChange=()=>{}}=$props();
 let moments=$state([]),selectedId=$state(''),title=$state(''),start=$state(0),end=$state(15),context=$state(''),recordingId=$state(''),recordingFit=$state(''),base=$state(''),loadedRevision=$state(0),busy=$state(false),error=$state(''),notice=$state(''),pending=$state(null),unknown=$state(false);
 let alive=true;
 let currentWorkspaceRevision=$state(0),open=$state(false),requiresSave=$state(false);
 const selected=$derived(moments.find(m=>m.id===selectedId));
 function values(){return {title,startSeconds:Number(start),endSeconds:Number(end),context,recordingId:recordingId||null,recordingFit};}
 const dirty=$derived(Boolean(pending)||requiresSave||(Boolean(base)&&JSON.stringify(values())!==base));
 $effect(()=>onDirtyChange(dirty));
 $effect(()=>onSelection(selected&&!dirty?$state.snapshot(selected):null));
 $effect(()=>{if(selected?.id&&selected.id===selectedMomentId)open=true;});
 function adopt(moment){requiresSave=false;selectedId=moment?.id||'';title=moment?.title||'';start=moment?.startSeconds??0;end=moment?.endSeconds??15;context=moment?.context||'';recordingId=moment?.recordingId||'';recordingFit=moment?.recordingFit||'';loadedRevision=moment?.revision||0;base=JSON.stringify(values());}
 $effect(()=>{selectedMomentId;moments;untrack(()=>{if(!dirty&&!busy)adopt(moments.find(m=>m.id===selectedMomentId));});});
 async function load(){if(busy)return;busy=true;error='';try{const result=await request('/inbox/moments?sourceId='+encodeURIComponent(source.id));if(alive){moments=result.moments;currentWorkspaceRevision=result.revision;}}catch(e){if(alive)error=e.message;}finally{if(alive)busy=false;}}
 function choose(id){if(busy||dirty)return;adopt(moments.find(m=>m.id===id));onMomentChange(id);notice='';}
 function save(){if(busy||pending)return;const value=values();if(!value.title.trim()||!Number.isFinite(value.startSeconds)||!Number.isFinite(value.endSeconds)||value.startSeconds<0||value.endSeconds>86400||value.endSeconds<=value.startSeconds||value.endSeconds-value.startSeconds>30){error='Add a title and choose a moment of up to 30 seconds.';return;}pending={expectedRevision:Math.max(revision,currentWorkspaceRevision),idempotencyKey:crypto.randomUUID(),sourceId:source.id,expectedSourceRevision:source.revision,...(selectedId?{expectedMomentRevision:loadedRevision}:{}),moment:{...(selectedId?{id:selectedId}:{}),...value}};void submit();}
 async function submit(){if(!pending||busy)return;busy=true;error='';notice='';try{const ack=await request('/inbox/moments',{method:'POST',body:JSON.stringify($state.snapshot(pending))});if(!alive)return;currentWorkspaceRevision=ack.revision;moments=[...moments.filter(m=>m.id!==ack.moment.id),ack.moment];pending=null;unknown=false;adopt(ack.moment);onMomentChange(ack.moment.id);notice='Human-selected moment saved';open=true;try{await onSaved(ack);}catch{error='Your moment is saved. Reload current references before the next save.';}}catch(e){if(!alive)return;error=e.status===409?'Saved references changed. Your selection is retained. Reload and compare before saving again.':e.message;unknown=!(Number.isInteger(e.status)&&e.status>=400&&e.status<500);if(!unknown)pending=null;}finally{if(alive)busy=false;}}
 function atTime(){const url=new URL(source.sourceUrl);url.searchParams.set('t',Math.floor(Math.max(0,Number(start)||0))+'s');return url.href;}
 onMount(()=>{adopt();void load();});onDestroy(()=>{alive=false;onDirtyChange(false);onSelection(null);});
</script>
<section class="human-moment" aria-label="Choose a moment yourself">
 <details bind:open><summary>Choose a moment yourself</summary><p class="research-meta">Watch the source, then save your own selection. Times and recording fit remain unverified.</p>
 {#if error}<p role="alert">{error}</p><button disabled={busy||unknown} onclick={load}>Reload saved selections</button>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if moments.length}<label>Saved human selections<select value={selectedId} disabled={busy||dirty} onchange={e=>choose(e.currentTarget.value)}><option value="">New selection</option>{#each moments as moment(moment.id)}<option value={moment.id}>{moment.title} · {moment.startSeconds}–{moment.endSeconds}s</option>{/each}</select></label>{/if}
 <fieldset disabled={busy||unknown}><label>Moment title<input bind:value={title} maxlength="200" placeholder="What makes this moment useful?"/></label><div class="moment-times"><label>Start (seconds)<input type="number" min="0" max="86400" step="0.1" bind:value={start}/></label><label>End (seconds)<input type="number" min="0" max="86400" step="0.1" bind:value={end}/></label></div><a href={atTime()} target="_blank" rel="noopener noreferrer">Open source at selected time ↗</a><label>Context<textarea bind:value={context} rows="2" maxlength="2000"></textarea></label><label>Proposed recording<select bind:value={recordingId}><option value="">No recording proposed</option>{#each recordings as recording(recording.id)}<option value={recording.id}>{recording.title}</option>{/each}</select></label><label>Why this recording fits<textarea bind:value={recordingFit} rows="2" maxlength="2000"></textarea></label></fieldset>
 {#if unknown}<button disabled={busy} onclick={submit}>Check same moment save</button>{:else}<button class="primary" disabled={busy||!title.trim()} onclick={save}>{busy?'Saving selection…':'Save human-selected moment'}</button>{/if}
 {#if selected&&selected.revision!==loadedRevision}<p>A newer selection is saved: {selected.title}, {selected.startSeconds}–{selected.endSeconds}s.</p><button disabled={busy||unknown} onclick={()=>{loadedRevision=selected.revision;requiresSave=true;notice='Working values retained. Save to replace this selection.';}}>Keep my values on this revision</button>{/if}
 {#if dirty&&!pending}<button disabled={busy} onclick={()=>{adopt(selected);error='';}}>Discard moment edits</button>{/if}
 {#if selected&&!dirty}<p class="research-meta">Human-selected · revision {selected.revision} · {selected.savedAt}</p><button onclick={()=>onUseMoment($state.snapshot(selected))}>Use saved selection for manual clip</button>{/if}
</details></section>
<style>.human-moment{padding:14px 0;border-bottom:1px solid var(--research-line)}.human-moment fieldset{border:0;padding:0;margin:10px 0;display:grid;gap:10px;min-width:0}.moment-times{display:grid;grid-template-columns:1fr 1fr;gap:10px}.human-moment fieldset>a{font-size:12px}.human-moment button{margin:6px 6px 0 0}</style>
